const devanagariFont = Buffer.from('','base64');
import PDFDocument from 'pdfkit';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
export function productCatalogPdf(business,products) {
 const doc=new PDFDocument({size:'A4',margin:40,bufferPages:true});
 doc.registerFont('Catalog',path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../fonts/DejaVuSans.ttf'));doc.font('Catalog');doc.registerFont('Devanagari',devanagariFont);
 const text=(value,options={})=>{const parts=String(value).match(/[\u0900-\u097f]+|[^\u0900-\u097f]+/g)||[''];parts.forEach((part,i)=>doc.font(/[\u0900-\u097f]/.test(part)?'Devanagari':'Catalog').text(part,{...options,continued:i<parts.length-1}));doc.font('Catalog');};
 const accent=/^#[0-9a-f]{6}$/i.test(business.accentColor||'')?business.accentColor:'#0e9f6e';
 doc.fontSize(10).fillColor(accent).text('PRODUCT CATALOG');
 doc.fontSize(25).fillColor('#162b1d');text(business.name);doc.moveDown(.35);
 doc.fontSize(10).fillColor('#526156').text(`${products.length} products | All catalog items, including hidden items`);doc.moveDown();
 for(const p of products) {
  const category=p.category?.name||'Uncategorized';
  const detail=`${category} | ₹${p.price} | Stock: ${p.kind==='service'?'Service':p.stock==null?'Unlimited':p.stock} | ${p.active?'Live':'Hidden'}`;
  const h=doc.heightOfString(p.name,{width:515})+doc.heightOfString(detail,{width:515})+doc.heightOfString(p.description||'',{width:515})+42;
  if(doc.y+Math.min(h,600)>770)doc.addPage();
  doc.fontSize(14).fillColor('#162b1d');text(p.name);doc.moveDown(.3);
  doc.fontSize(10).fillColor(accent);text(detail);doc.moveDown(.35);
  if(p.description){doc.fontSize(10).fillColor('#526156');text(p.description,{lineGap:3});}
  doc.moveDown(.7);doc.strokeColor('#e1e5df').moveTo(40,doc.y).lineTo(555,doc.y).stroke();doc.moveDown(.7);
 }
 const range=doc.bufferedPageRange();
 for(let i=0;i<range.count;i++){doc.switchToPage(i);doc.fontSize(8).fillColor('#6c786f').text(`Digital Shop · ${i+1} / ${range.count}`,40,775,{width:515,align:'right',lineBreak:false});}
 return doc;
}
